def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    if n == 0:
        return []

    # Determine if input is adjacency matrix or list
    is_matrix = False
    if n > 0 and len(adj[0]) == n:
        # Check if all entries are 0 or 1 (binary)
        is_matrix = True
        for i in range(n):
            if len(adj[i]) != n:
                is_matrix = False
                break
            for val in adj[i]:
                if val not in (0, 1):
                    is_matrix = False
                    break
            if not is_matrix:
                break

    if is_matrix:
        # Convert adjacency matrix to adjacency list
        graph = [[] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    graph[i].append(j)
    else:
        # Treat as adjacency list
        graph = adj

    # Handle trivial cases
    if n == 1:
        return [0]

    # Check if graph is edgeless
    has_edge = any(len(graph[i]) > 0 for i in range(n))
    if not has_edge:
        return [0] * n

    # Compute degrees
    deg = [len(graph[i]) for i in range(n)]

    # Welsh-Powell heuristic for initial upper bound
    order_wp = sorted(range(n), key=lambda x: (-deg[x], x))
    color_wp = [-1] * n
    max_color_wp = 0
    for v in order_wp:
        neighbor_colors = set()
        for u in graph[v]:
            if color_wp[u] != -1:
                neighbor_colors.add(color_wp[u])
        c = 0
        while c in neighbor_colors:
            c += 1
        color_wp[v] = c
        if c > max_color_wp:
            max_color_wp = c
    ub = max_color_wp + 1

    # DSATUR algorithm to get a good initial solution and ordering
    def dsatur():
        color = [-1] * n
        saturated = [set() for _ in range(n)]
        colored_count = 0
        while colored_count < n:
            # Select uncolored vertex with max saturation degree, tie-break by degree in uncolored subgraph
            max_sat = -1
            candidates = []
            for v in range(n):
                if color[v] == -1:
                    sat = len(saturated[v])
                    if sat > max_sat:
                        max_sat = sat
                        candidates = [v]
                    elif sat == max_sat:
                        candidates.append(v)
            # Tie-break: max degree in uncolored subgraph
            if len(candidates) > 1:
                max_deg_uncolored = -1
                selected = candidates[0]
                for v in candidates:
                    deg_uncolored = 0
                    for u in graph[v]:
                        if color[u] == -1:
                            deg_uncolored += 1
                    if deg_uncolored > max_deg_uncolored:
                        max_deg_uncolored = deg_uncolored
                        selected = v
                    elif deg_uncolored == max_deg_uncolored and v < selected:
                        selected = v
                v = selected
            else:
                v = candidates[0]
            # Assign smallest available color
            used = saturated[v]
            c = 0
            while c in used:
                c += 1
            color[v] = c
            colored_count += 1
            # Update saturation of uncolored neighbors
            for u in graph[v]:
                if color[u] == -1:
                    saturated[u].add(c)
        return color

    dsatur_color = dsatur()
    dsatur_ub = max(dsatur_color) + 1 if dsatur_color else 0
    if dsatur_ub < ub:
        ub = dsatur_ub
        best_color = dsatur_color[:]
    else:
        best_color = color_wp[:]

    # Try to improve using Kempe chain swaps
    def kempe_improve(color, current_ub):
        # Try to eliminate the highest color class
        for target_color in range(current_ub - 1, -1, -1):
            # Build list of vertices with color > target_color, focusing on highest first
            vertices_by_color = [[] for _ in range(current_ub)]
            for v in range(n):
                c = color[v]
                if c < current_ub:
                    vertices_by_color[c].append(v)
            # Process from highest color down to target_color+1
            for c in range(current_ub - 1, target_color, -1):
                if not vertices_by_color[c]:
                    continue
                # Try to recolor each vertex in color c to a color < c
                for v in vertices_by_color[c][:]:  # iterate over a copy
                    # Try direct reassignment to any color < c
                    neighbor_colors = set()
                    for u in graph[v]:
                        if color[u] < c:
                            neighbor_colors.add(color[u])
                    for new_c in range(c):
                        if new_c not in neighbor_colors:
                            # Direct move possible
                            color[v] = new_c
                            vertices_by_color[c].remove(v)
                            vertices_by_color[new_c].append(v)
                            break
                    else:
                        # Try Kempe chains for each color new_c < c
                        for new_c in range(c):
                            # BFS to find the (v, new_c)-Kempe chain component containing v
                            from collections import deque
                            visited = [False] * n
                            queue = deque([v])
                            visited[v] = True
                            component = []
                            while queue:
                                node = queue.popleft()
                                component.append(node)
                                for neighbor in graph[node]:
                                    if not visited[neighbor] and color[neighbor] in (new_c, c):
                                        visited[neighbor] = True
                                        queue.append(neighbor)
                            # Check if any neighbor of the component has color new_c (would cause conflict if swapped)
                            conflict = False
                            for node in component:
                                for neighbor in graph[node]:
                                    if color[neighbor] == new_c and not visited[neighbor]:
                                        conflict = True
                                        break
                                if conflict:
                                    break
                            if not conflict:
                                # Perform swap: c -> new_c, new_c -> c in the component
                                for node in component:
                                    if color[node] == c:
                                        color[node] = new_c
                                    elif color[node] == new_c:
                                        color[node] = c
                                # Update vertices_by_color
                                # Remove from color c and add to new_c for those that were c
                                # Remove from new_c and add to c for those that were new_c
                                # Since we are processing color c, we know v was in c and will move to new_c
                                # But other nodes in the component might change color class
                                # Rebuild vertices_by_color for simplicity (n is small)
                                for col in range(current_ub):
                                    vertices_by_color[col] = [node for node in range(n) if color[node] == col]
                                break  # break new_c loop after successful swap
                        else:
                            continue  # only executed if inner loop did NOT break
                        break  # break new_c loop if we broke out (swap done)
                    # If we reassigned v (direct or Kempe), break to reprocess color c
                    if color[v] < c:
                        break
                # After attempting to recolor all vertices in color c, check if color c is empty
                if not vertices_by_color[c]:
                    # Color c is eliminated, we can reduce the upper bound
                    current_ub = c
                    # Rebuild vertices_by_color for new current_ub
                    vertices_by_color = [[] for _ in range(current_ub)]
                    for v in range(n):
                        if color[v] < current_ub:
                            vertices_by_color[color[v]].append(v)
                    # Break out to try to eliminate the new highest color
                    break
            else:
                # Continue to next target_color if inner loop didn't break (meaning we didn't eliminate a color)
                continue
            # If we broke out because we eliminated a color, try to eliminate again from the new highest
            if current_ub <= target_color:
                break
        return color, current_ub

    # Apply Kempe improvement iteratively
    improved_color, improved_ub = kempe_improve(best_color[:], ub)
    if improved_ub < ub:
        ub = improved_ub
        best_color = improved_color

    # Final verification: ensure coloring is valid
    for v in range(n):
        for u in graph[v]:
            if best_color[v] == best_color[u]:
                # Fallback to DSATUR if something went wrong
                best_color = dsatur_color
                ub = dsatur_ub
                break
        else:
            continue
        break

    return best_color

