def color_graph(adj: list[list[int]]) -> list[int]:
    # Handle empty graph
    if not adj:
        return []
    n = len(adj)

    # Detect adjacency matrix vs adjacency list
    is_matrix = False
    if n > 0 and isinstance(adj[0], list) and len(adj[0]) == n:
        # Check if all entries are 0 or 1 (binary)
        all_binary = True
        for i in range(n):
            for j in range(n):
                val = adj[i][j]
                if val != 0 and val != 1:
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True

    # Build neighbor sets for efficient access
    neighbors = [set() for _ in range(n)]
    if is_matrix:
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    neighbors[i].add(j)
    else:
        for i in range(n):
            if isinstance(adj[i], list):
                for j in adj[i]:
                    if 0 <= j < n:
                        neighbors[i].add(j)

    # Remove self-loops if any
    for i in range(n):
        if i in neighbors[i]:
            neighbors[i].remove(i)

    # Trivial cases
    if n == 1:
        return [0]
    if all(len(neighbors[i]) == 0 for i in range(n)):
        return [0] * n

    # Compute degeneracy ordering (smallest-last) for initial bound
    def degeneracy_ordering():
        deg = [len(neighbors[i]) for i in range(n)]
        removed = [False] * n
        order = []
        buckets = [[] for _ in range(n)]
        max_deg = max(deg) if n > 0 else 0
        for i in range(n):
            if deg[i] < n:
                buckets[deg[i]].append(i)
        ptr = 0
        for _ in range(n):
            while ptr <= max_deg and not buckets[ptr]:
                ptr += 1
            if ptr > max_deg:
                break
            v = buckets[ptr].pop()
            if removed[v]:
                continue
            removed[v] = True
            order.append(v)
            for u in neighbors[v]:
                if not removed[u]:
                    d = deg[u]
                    if d > 0:
                        deg[u] -= 1
                        if deg[u] < n:
                            buckets[deg[u]].append(u)
        return order

    order = degeneracy_ordering()
    # Color in reverse degeneracy order (largest last) for initial upper bound
    color = [-1] * n
    for v in reversed(order):
        used = [False] * (n + 1)
        for u in neighbors[v]:
            if color[u] != -1:
                used[color[u]] = True
        c = 0
        while c <= n and used[c]:
            c += 1
        color[v] = c
    ub = max(color) + 1 if n > 0 else 0

    # If ub is 1, we are done (edgeless)
    if ub <= 1:
        return color

    # Try to improve using DSATUR with backtracking
    best_color = color[:]
    best_ub = ub

    # DSATUR-based recursive backtracking with pruning
    def dsatur_backtrack(current_color, num_colors, colored_count):
        nonlocal best_color, best_ub

        # Prune if already using too many colors
        if num_colors >= best_ub:
            return

        if colored_count == n:
            # Found a valid coloring
            best_ub = num_colors
            best_color = current_color[:]
            return

        # Select uncolored vertex with max saturation degree
        max_sat = -1
        candidates = []
        for v in range(n):
            if current_color[v] == -1:
                # Compute saturation degree: number of distinct colors in neighbors
                neighbor_colors = set()
                for u in neighbors[v]:
                    if current_color[u] != -1:
                        neighbor_colors.add(current_color[u])
                sat = len(neighbor_colors)
                if sat > max_sat:
                    max_sat = sat
                    candidates = [v]
                elif sat == max_sat:
                    candidates.append(v)

        if not candidates:
            return

        # Tie-break by degree in uncolored subgraph, then randomly
        def uncolored_degree(v):
            return sum(1 for u in neighbors[v] if current_color[u] == -1)

        candidates.sort(key=lambda v: (-uncolored_degree(v), v))
        # Shuffle to break ties randomly, but limit to avoid too much randomness
        random.shuffle(candidates)
        # Limit branching factor
        if len(candidates) > 3:
            candidates = candidates[:3]

        for v in candidates:
            # Try colors from 0 to num_colors (inclusive) - we allow one new color
            used = [False] * (num_colors + 1)
            for u in neighbors[v]:
                if current_color[u] != -1:
                    used[current_color[u]] = True
            for c in range(num_colors + 1):
                if not used[c]:
                    current_color[v] = c
                    new_num_colors = max(num_colors, c + 1)
                    dsatur_backtrack(current_color, new_num_colors, colored_count + 1)
                    current_color[v] = -1
                    # If we found a coloring equal to current best_ub, we can stop early for this vertex
                    if best_ub <= num_colors:
                        return

    # Start backtracking from the initial upper bound
    dsatur_backtrack(color[:], ub, n)

    return best_color

