def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect input type: adjacency matrix (square 0/1) or adjacency list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        is_matrix = True
        for row in adj:
            if len(row) != len(adj):
                is_matrix = False
                break
            for val in row:
                if val not in (0, 1):
                    is_matrix = False
                    break
            if not is_matrix:
                break

    # Build neighbor sets for efficient access
    if is_matrix:
        neighbors = [set(j for j, val in enumerate(row) if val == 1) for row in adj]
    else:
        neighbors = [set(lst) for lst in adj]

    # DSATUR algorithm
    colors = [-1] * n
    saturated = [set() for _ in range(n)]
    uncolored = set(range(n))

    # Helper to get degree in uncolored subgraph
    def degree_in_uncolored(v):
        return sum(1 for u in neighbors[v] if u in uncolored)

    # Main loop: color vertices one by one
    while uncolored:
        # Select vertex with max saturation degree, tie-break by degree in uncolored, then random
        v = max(uncolored, key=lambda x: (len(saturated[x]), degree_in_uncolored(x), random.random()))
        # Find smallest available color (mex)
        used = saturated[v]
        c = 0
        while c in used:
            c += 1
        colors[v] = c
        uncolored.remove(v)
        # Update saturation sets of uncolored neighbors
        for u in neighbors[v]:
            if u in uncolored:
                saturated[u].add(c)

    # Kempe chain refinement to minimize color count
    max_color = max(colors) if n > 0 else -1
    if max_color < 0:
        return colors

    # Try to reduce colors from highest down
    for k in range(max_color, 0, -1):
        # Vertices with color k
        Vk = [v for v in range(n) if colors[v] == k]
        if not Vk:
            continue  # This color already eliminated
        made_progress = True
        while made_progress and Vk:
            made_progress = False
            # Try to recolor each vertex in Vk
            for v in Vk[:]:  # iterate over a copy
                if colors[v] != k:
                    continue  # already recolored
                # Try direct reassignment to a lower color
                for c in range(k):
                    if all(colors[u] != c for u in neighbors[v]):
                        colors[v] = c
                        made_progress = True
                        Vk.remove(v)
                        break
                if colors[v] == k:
                    # Try Kempe chain swap for each lower color
                    for c in range(k):
                        # Build the (k, c)-Kempe chain component containing v via BFS
                        visited = set()
                        stack = [v]
                        visited.add(v)
                        while stack:
                            node = stack.pop()
                            for u in neighbors[node]:
                                if u not in visited and colors[u] in (k, c):
                                    visited.add(u)
                                    stack.append(u)
                        # Check if any neighbor of v has color c (would cause conflict if swapped)
                        conflict = any(colors[u] == c for u in neighbors[v])
                        if not conflict:
                            # Swap colors k and c in the component
                            for node in visited:
                                if colors[node] == k:
                                    colors[node] = c
                                elif colors[node] == c:
                                    colors[node] = k
                            made_progress = True
                            if v in Vk:
                                Vk.remove(v)
