    else:
        adj_list = adj
        # Ensure elements are integers
        for i in range(n):
            adj_list[i] = [int(x) for x in adj_list[i]]

    # Trivial cases
    if n == 1:
        return [0]
    if all(len(adj_list[i]) == 0 for i in range(n)):
        return [0] * n

