    # Welsh-Powell initial coloring for upper bound
    order_wp = sorted(range(n), key=lambda x: (-degrees[x], x))
    color_wp = [-1] * n
    for v in order_wp:
        used = [False] * (n + 1)
        for u in adj_list[v]:
            if color_wp[u] != -1:
                used[color_wp[u]] = True
        c = 0
        while c < n and used[c]:
            c += 1
        color_wp[v] = c
