        used = set()
        for u in adj_list[v]:
            if color_arr[u] != -1:
                used.add(color_arr[u])
        return len(used)

    # Helper: degree in uncolored subgraph
    def uncolored_degree(v, color_arr):
        cnt = 0
        for u in adj_list[v]:
            if color_arr[u] == -1:
                cnt += 1
        return cnt

    # DSATUR with iterative refinement
    def dsatur_refine():
        color = [-1] * n
        uncolored = set(range(n))

        while uncolored:
            # Select vertex with max saturation, tie-break by uncolored degree, then random
            v = -1
            max_sat = -1
            max_deg = -1
            for u in uncolored:
                sat_u = saturation_degree(u, color)
                deg_u = uncolored_degree(u, color)
                if sat_u > max_sat or (sat_u == max_sat and deg_u > max_deg) or \
                   (sat_u == max_sat and deg_u == max_deg and random.random() < 0.5):
                    max_sat = sat_u
                    max_deg = deg_u
                    v = u

            # Assign smallest available color
            used = [False] * (n + 1)
            for u in adj_list[v]:
                if color[u] != -1:
                    used[color[u]] = True
            c = 0
            while c <= n and used[c]:
                c += 1
            color[v] = c
            uncolored.remove(v)

