    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        current_color = 0

        while uncolored:
            # Start new color class: pick vertex with max degree in G[uncolored]
            v = -1
            max_deg = -1
            for u in uncolored:
                deg = 0
                for w in adj_list[u]:
                    if w in uncolored:
                        deg += 1
                if deg > max_deg:
                    max_deg = deg
                    v = u
