            while U:
                # Select u in U with max |N(u) ∩ W|, tie-break by min degree in G[U], then random
                u_best = -1
                max_common = -1
                min_deg_U = float('inf')
                for u in U:
                    common = 0
                    for w in adj_list[u]:
                        if w in W:
                            common += 1
                    deg_U = 0
                    for w in adj_list[u]:
                        if w in U:
                            deg_U += 1
                    if common > max_common or (common == max_common and deg_U < min_deg_U) or \
                       (common == max_common and deg_U == min_deg_U and random.random() < 0.5):
                        max_common = common
                        min_deg_U = deg_U
                        u_best = u

                # Add u_best to S and update U, W
                S.add(u_best)
                U.remove(u_best)
                for w in adj_list[u_best]:
                    if w in U:
                        U.remove(w)
                        W.add(w)

            # Assign color to S
            for u in S:
                color[u] = current_color
                uncolored.remove(u)
            current_color += 1

        return color

    # Run RLF multiple times
    for _ in range(20):
        col = rlf()
        k = max(col) + 1 if n > 0 else 0
        if k < best_k:
            best_k = k
            best_coloring = col[:]
            if best_k == 1:
                break

    # Kempe chain refinement to reduce color count
    def kempe_reduce(coloring):
        color = coloring[:]
        k = max(color) + 1 if n > 0 else 0
        improved = True
        while improved and k > 1:
            improved = False
            # Vertices with color k-1
            class_k = [v for v in range(n) if color[v] == k - 1]
            if not class_k:
                k -= 1
                continue

            for v in class_k:
                # Try direct move to a lower color
                moved = False
                for c in range(k - 1):
                    if all(color[u] != c for u in adj_list[v]):
                        color[v] = c
                        moved = True
                        improved = True
                        break
                if moved:
                    break  # restart Kempe reduction from scratch

                # Try Kempe chain swap for each lower color
                for c in range(k - 1):
                    # BFS for (c, k-1)-Kempe chain containing v
                    visited = set()
                    stack = [v]
                    visited.add(v)
                    while stack:
                        node = stack.pop()
                        for nb in adj_list[node]:
                            if nb not in visited and color[nb] in (c, k - 1):
                                visited.add(nb)
                                stack.append(nb)

                    # Check if swapping is safe: no neighbor of v will become color c after swap
                    safe = True
                    for u in adj_list[v]:
                        if u in visited:
                            if color[u] == k - 1:  # after swap becomes c -> conflict
                                safe = False
                                break
                        else:
                            if color[u] == c:      # remains c -> conflict
                                safe = False
                                break
                    if safe:
                        # Perform swap
                        for node in visited:
                            if color[node] == c:
                                color[node] = k - 1
                            else:  # must be k-1
                                color[node] = c
                        improved = True
                        break  # break color loop
                if improved:
                    break  # break vertex loop to restart

        return color, max(color) + 1 if n > 0 else 0

    # Apply Kempe reduction
    final_color, final_k = kempe_reduce(best_coloring)
    if final_k < best_k:
        best_k = final_k
        best_coloring = final_color

    return best_coloring

